_PRICING_CODES = ("pricing.view",)


def seed_pricing_permissions(apps: "Apps", schema_editor: "BaseDatabaseSchemaEditor") -> None:
    """Insert the pricing permission codenames (idempotent upsert)."""
    permission_model = apps.get_model("accounts", "Permission")
    for perm in PERMISSIONS:
        if perm.code not in _PRICING_CODES:
            continue
        permission_model.objects.update_or_create(
            code=perm.code,
            defaults={"module": perm.module, "name": perm.name, "is_sensitive": perm.sensitive},
        )


def unseed_pricing_permissions(apps: "Apps", schema_editor: "BaseDatabaseSchemaEditor") -> None:
    permission_model = apps.get_model("accounts", "Permission")
    permission_model.objects.filter(code__in=_PRICING_CODES).delete()


